test_cases.then:
then {
    the client at '${endpoint}' receives a valid Notification containing:
        Notification received Waiting for no Notification data and
    Query Parameter: timeout set to '5'
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
